import java.math.BigInteger;

class Solution {
    public String abbreviateProduct(int left, int right) {
        String digits = rangeProduct(left, right).toString();

        int end = digits.length();
        while (digits.charAt(end - 1) == '0') {
            end--;
        }

        int zeros = digits.length() - end;
        if (end <= 10) {
            return digits.substring(0, end) + "e" + zeros;
        }

        return digits.substring(0, 5) + "..."
                + digits.substring(end - 5, end) + "e" + zeros;
    }

    private BigInteger rangeProduct(int left, int right) {
        if (right - left <= 3) {
            long product = 1;
            for (int value = left; value <= right; value++) {
                product *= value;
            }
            return BigInteger.valueOf(product);
        }

        int middle = left + (right - left) / 2;
        return rangeProduct(left, middle)
                .multiply(rangeProduct(middle + 1, right));
    }
}
