import java.util.ArrayList;
import java.util.List;

class Solution {
    public List<String> ambiguousCoordinates(String s) {
        String digits = s.substring(1, s.length() - 1);
        List<String> result = new ArrayList<>();

        for (int split = 1; split < digits.length(); split++) {
            List<String> left = representations(digits.substring(0, split));
            List<String> right = representations(digits.substring(split));

            for (String x : left) {
                for (String y : right) {
                    result.add("(" + x + ", " + y + ")");
                }
            }
        }

        return result;
    }

    private List<String> representations(String digits) {
        List<String> result = new ArrayList<>();
        int n = digits.length();

        if (n == 1 || digits.charAt(0) != '0') {
            result.add(digits);
        }

        // A fractional part cannot end in zero.
        if (digits.charAt(n - 1) == '0') {
            return result;
        }

        for (int point = 1; point < n; point++) {
            // Only "0" is allowed as an integer part starting with zero.
            if (point > 1 && digits.charAt(0) == '0') {
                break;
            }
            result.add(digits.substring(0, point) + "." + digits.substring(point));
        }

        return result;
    }
}
