class Solution {
    public boolean canCross(int[] stones) {
        int n = stones.length;
        if (stones[1] != 1) {
            return false;
        }

        // reachable[i][k]: stone i can be reached with a jump of length k.
        boolean[][] reachable = new boolean[n][n + 1];
        reachable[0][0] = true;

        for (int i = 1; i < n; i++) {
            for (int j = i - 1; j >= 0; j--) {
                int jump = stones[i] - stones[j];

                // From stone j, the next jump cannot exceed j + 1.
                // Earlier stones only increase the gap and reduce this bound.
                if (jump > j + 1) {
                    break;
                }

                reachable[i][jump] =
                        reachable[j][jump - 1]
                        || reachable[j][jump]
                        || reachable[j][jump + 1];

                if (i == n - 1 && reachable[i][jump]) {
                    return true;
                }
            }
        }

        return false;
    }
}
