class Solution {
    public int countTriples(int n) {
        int count = 0;
        int maxSquare = n * n;

        for (int a = 1; a <= n; a++) {
            for (int b = a + 1; b <= n; b++) {
                int sum = a * a + b * b;
                if (sum > maxSquare) {
                    break;
