class Solution {
    public int maxScore(int[] nums) {
        int m = nums.length;
        int[][] gcds = new int[m][m];
        for (int i = 0; i < m; i++) {
            for (int j = i + 1; j < m; j++) {
                gcds[i][j] = gcd(nums[i], nums[j]);
            }
        }

        int[] dp = new int[1 << m];

        for (int mask = 1; mask < dp.length; mask++) {
            int count = Integer.bitCount(mask);
            if ((count & 1) != 0) {
                continue;
            }

            int operation = count / 2;
            for (int i = 0; i < m; i++) {
                if ((mask & (1 << i)) == 0) {
                    continue;
                }
                for (int j = i + 1; j < m; j++) {
                    if ((mask & (1 << j)) == 0) {
                        continue;
                    }

                    int previousMask = mask ^ (1 << i) ^ (1 << j);
                    dp[mask] = Math.max(
                        dp[mask],
                        dp[previousMask] + operation * gcds[i][j]
                    );
                }
            }
        }

        return dp[dp.length - 1];
    }

    private int gcd(int a, int b) {
        while (b != 0) {
            int remainder = a % b;
            a = b;
            b = remainder;
        }
        return a;
    }
}
