class Solution {
    public int countVowelSubstrings(String word) {
        int[] lastSeen = {-1, -1, -1, -1, -1};
        String vowels = "aeiou";
        int lastConsonant = -1;
        int count = 0;

        for (int i = 0; i < word.length(); i++) {
            int vowelIndex = vowels.indexOf(word.charAt(i));

            if (vowelIndex == -1) {
                lastConsonant = i;
                continue;
            }

            lastSeen[vowelIndex] = i;

            int earliest = lastSeen[0];
            for (int j = 1; j < 5; j++) {
                earliest = Math.min(earliest, lastSeen[j]);
            }

            // Valid starts lie after the last consonant and at most at earliest.
            count += Math.max(0, earliest - lastConsonant);
        }

        return count;
    }
}
