class Solution {
    public int maximumANDSum(int[] nums, int numSlots) {
        // Each ternary digit records a slot's occupancy: 0, 1, or 2.
        int[] powers = new int[numSlots];
        int totalStates = 1;
        for (int slot = 0; slot < numSlots; slot++) {
            powers[slot] = totalStates;
            totalStates *= 3;
        }

        int[] dp = new int[totalStates];
        int[] placed = new int[totalStates];
        java.util.Arrays.fill(dp, -1);
        dp[0] = 0;

        int answer = 0;
        for (int state = 0; state < totalStates; state++) {
            if (state > 0) {
                placed[state] = placed[state / 3] + state % 3;
            }

            if (dp[state] == -1) {
                continue;
            }

            int index = placed[state];
            if (index == nums.length) {
                answer = Math.max(answer, dp[state]);
                continue;
            }

            int digits = state;
            for (int slot = 0; slot < numSlots; slot++) {
                if (digits % 3 < 2) {
                    int nextState = state + powers[slot];
                    int score = dp[state] + (nums[index] & (slot + 1));
                    dp[nextState] = Math.max(dp[nextState], score);
                }
                digits /= 3;
            }
        }

        return answer;
    }
}
