class Solution {
    public long maxRunTime(int n, int[] batteries) {
        long total = 0;
        for (int battery : batteries) {
            total += battery;
        }

        long low = 0;
        long high = total / n;

        while (low < high) {
            long mid = low + (high - low + 1) / 2;
            long required = mid * n;
            long available = 0;

            for (int battery : batteries) {
                available += Math.min((long) battery, mid);
                if (available >= required) {
                    break;
                }
            }

            if (available >= required) {
                low = mid;
            } else {
                high = mid - 1;
            }
        }

        return low;
    }
}
