class Solution {
    public int largestMagicSquare(int[][] grid) {
        int m = grid.length;
        int n = grid[0].length;

        int[][] rowPrefix = new int[m][n + 1];
        int[][] colPrefix = new int[m + 1][n];
        int[][] diagonal = new int[m + 1][n + 1];
        int[][] antiDiagonal = new int[m + 1][n + 1];

        for (int r = 0; r < m; r++) {
            for (int c = 0; c < n; c++) {
                int value = grid[r][c];
                rowPrefix[r][c + 1] = rowPrefix[r][c] + value;
                colPrefix[r + 1][c] = colPrefix[r][c] + value;
                diagonal[r + 1][c + 1] = diagonal[r][c] + value;
                antiDiagonal[r + 1][c] = antiDiagonal[r][c + 1] + value;
            }
        }

        for (int size = Math.min(m, n); size >= 2; size--) {
            for (int r = 0; r + size <= m; r++) {
                for (int c = 0; c + size <= n; c++) {
                    int target = rowPrefix[r][c + size] - rowPrefix[r][c];

                    int mainSum = diagonal[r + size][c + size] - diagonal[r][c];
                    int antiSum = antiDiagonal[r + size][c] - antiDiagonal[r][c + size];

                    if (mainSum != target || antiSum != target) {
                        continue;
                    }

                    boolean valid = true;
                    for (int offset = 0; offset < size; offset++) {
                        int rowSum = rowPrefix[r + offset][c + size]
                                - rowPrefix[r + offset][c];
                        int colSum = colPrefix[r + size][c + offset]
                                - colPrefix[r][c + offset];

                        if (rowSum != target || colSum != target) {
                            valid = false;
                            break;
                        }
                    }

                    if (valid) {
                        return size;
                    }
                }
            }
        }

        return 1;
    }
}
