class Solution {
    public long maximumBeauty(int[] flowers, long newFlowers, int target, int full, int partial) {
        java.util.Arrays.sort(flowers);
        int n = flowers.length;

        int incomplete = n;
        while (incomplete > 0 && flowers[incomplete - 1] >= target) {
            incomplete--;
        }

        if (incomplete == 0) {
            return (long) n * full;
        }

        long[] prefix = new long[incomplete + 1];
        for (int i = 0; i < incomplete; i++) {
            prefix[i + 1] = prefix[i] + flowers[i];
        }

        long answer = 0;
        long remainingFlowers = newFlowers;

        // Complete the largest incomplete gardens first.
        for (int remaining = incomplete; remaining >= 0; remaining--) {
            if (remainingFlowers < 0) {
                break;
            }

            long beauty = (long) (n - remaining) * full;
            if (remaining == 0) {
                answer = Math.max(answer, beauty);
                break;
            }

            // Find the largest prefix that can be leveled to its maximum.
            int low = 1;
            int high = remaining;
            while (low < high) {
                int mid = low + (high - low + 1) / 2;
                long cost = (long) flowers[mid - 1] * mid - prefix[mid];

                if (cost <= remainingFlowers) {
                    low = mid;
                } else {
                    high = mid - 1;
                }
            }

            long minimum = Math.min(
                target - 1L,
                (remainingFlowers + prefix[low]) / low
            );

            answer = Math.max(answer, beauty + minimum * partial);
            remainingFlowers -= target - flowers[remaining - 1];
        }

        return answer;
    }
}
