class Solution {
    public int minMalwareSpread(int[][] graph, int[] initial) {
        int n = graph.length;
        boolean[] infected = new boolean[n];
        for (int node : initial) {
            infected[node] = true;
        }

        boolean[] visited = new boolean[n];
        int[] saved = new int[n];
        int[] queue = new int[n];

        // Find components consisting only of initially uninfected nodes.
        for (int start = 0; start < n; start++) {
            if (infected[start] || visited[start]) {
                continue;
            }

            int head = 0;
            int tail = 0;
            queue[tail++] = start;
            visited[start] = true;

            // -1: no infected neighbor; -2: multiple infected neighbors.
            int owner = -1;

            while (head < tail) {
                int node = queue[head++];

                for (int neighbor = 0; neighbor < n; neighbor++) {
                    if (graph[node][neighbor] == 0) {
                        continue;
                    }

                    if (infected[neighbor]) {
                        if (owner == -1) {
                            owner = neighbor;
                        } else if (owner != neighbor) {
                            owner = -2;
                        }
                    } else if (!visited[neighbor]) {
                        visited[neighbor] = true;
                        queue[tail++] = neighbor;
                    }
                }
            }

            // Removing the sole infection source saves this entire component.
            if (owner >= 0) {
                saved[owner] += tail;
            }
        }

        int answer = initial[0];
        for (int node : initial) {
            if (saved[node] > saved[answer]
                    || (saved[node] == saved[answer] && node < answer)) {
                answer = node;
            }
        }

        return answer;
    }
}
