class Solution {
    public int minCost(int maxTime, int[][] edges, int[] passingFees) {
        int n = passingFees.length;
        int inf = Integer.MAX_VALUE / 2;

        // dp[t][city]: minimum cost to reach city in exactly t minutes.
        int[][] dp = new int[maxTime + 1][n];
        for (int[] row : dp) {
            java.util.Arrays.fill(row, inf);
        }
        dp[0][0] = passingFees[0];

        int answer = inf;
        for (int time = 1; time <= maxTime; time++) {
            for (int[] edge : edges) {
                int u = edge[0];
                int v = edge[1];
                int travelTime = edge[2];

                if (travelTime > time) {
                    continue;
                }

                int previousTime = time - travelTime;
                if (dp[previousTime][u] != inf) {
                    dp[time][v] = Math.min(
                        dp[time][v],
                        dp[previousTime][u] + passingFees[v]
                    );
                }
                if (dp[previousTime][v] != inf) {
                    dp[time][u] = Math.min(
                        dp[time][u],
                        dp[previousTime][v] + passingFees[u]
                    );
                }
            }
            answer = Math.min(answer, dp[time][n - 1]);
        }

        return answer == inf ? -1 : answer;
    }
}
