            for (int c = 0; c < n; c++) {
                int start = r * n + c;
                if (grid[r][c] == 0 || visited[start]) {
                    continue;
                }

                if (++islands == 2) {
                    return 2;
                }

                int head = 0;
                int tail = 0;
                queue[tail++] = start;
                visited[start] = true;

                while (head < tail) {
                    int cell = queue[head++];
                    int row = cell / n;
                    int col = cell % n;

                    for (int d = 0; d < 4; d++) {
                        int nr = row + DR[d];
                        int nc = col + DC[d];

                        if (nr < 0 || nr >= m || nc < 0 || nc >= n) {
                            continue;
                        }

                        int next = nr * n + nc;
                        if (grid[nr][nc] == 1 && !visited[next]) {
                            visited[next] = true;
                            queue[tail++] = next;
                        }
                    }
                }
            }
        }

        return islands;
    }
}
