class Solution {
    public int maxSizeSlices(int[] slices) {
        int picks = slices.length / 3;
        return Math.max(
            maxLinear(slices, 0, slices.length - 2, picks),
            maxLinear(slices, 1, slices.length - 1, picks)
        );
    }

    private int maxLinear(int[] slices, int start, int end, int picks) {
        int[] previousTwo = new int[picks + 1];
        int[] previousOne = new int[picks + 1];
        int[] current = new int[picks + 1];

        java.util.Arrays.fill(previousTwo, Integer.MIN_VALUE);
        java.util.Arrays.fill(previousOne, Integer.MIN_VALUE);
        previousTwo[0] = previousOne[0] = 0;

        for (int i = start; i <= end; i++) {
            current[0] = 0;
            for (int count = 1; count <= picks; count++) {
                current[count] = previousOne[count];
                if (previousTwo[count - 1] != Integer.MIN_VALUE) {
                    current[count] = Math.max(
                        current[count],
                        previousTwo[count - 1] + slices[i]
                    );
                }
            }

            int[] temporary = previousTwo;
            previousTwo = previousOne;
            previousOne = current;
            current = temporary;
        }

        return previousOne[picks];
    }
}
