class Solution {
    public int[] nextGreaterElements(int[] nums) {
        int n = nums.length;
        int[] result = new int[n];
        java.util.Arrays.fill(result, -1);

        int[] stack = new int[n];
        int size = 0;

        for (int i = 0; i < 2 * n; i++) {
            int index = i % n;

            while (size > 0 && nums[stack[size - 1]] < nums[index]) {
                result[stack[--size]] = nums[index];
            }

            if (i < n) {
                stack[size++] = index;
            }
        }

        return result;
    }
}
