import java.util.HashMap;
import java.util.Map;

class Solution {
    public int numTriplets(int[] nums1, int[] nums2) {
        return countTriplets(nums1, nums2) + countTriplets(nums2, nums1);
    }

    private int countTriplets(int[] squaredNumbers, int[] pairedNumbers) {
        Map<Long, Integer> squareFrequency = new HashMap<>();

        for (int number : squaredNumbers) {
            long square = (long) number * number;
            squareFrequency.put(square, squareFrequency.getOrDefault(square, 0) + 1);
        }

        int count = 0;
        for (int j = 0; j < pairedNumbers.length; j++) {
            for (int k = j + 1; k < pairedNumbers.length; k++) {
                long product = (long) pairedNumbers[j] * pairedNumbers[k];
                count += squareFrequency.getOrDefault(product, 0);
            }
        }

        return count;
    }
}
