import java.util.Map;

class Solution {
    public int minStickers(String[] stickers, String target) {
        int[][] counts = new int[stickers.length][26];
        boolean[] available = new boolean[26];

        for (int i = 0; i < stickers.length; i++) {
            for (char c : stickers[i].toCharArray()) {
                counts[i][c - 'a']++;
                available[c - 'a'] = true;
            }
        }

        for (char c : target.toCharArray()) {
            if (!available[c - 'a']) {
                return -1;
            }
        }

        Map<String, Integer> memo = new HashMap<>();
        memo.put("", 0);
        return solve(target, counts, memo);
    }

    private int solve(String remaining, int[][] stickers,
                      Map<String, Integer> memo) {
        Integer cached = memo.get(remaining);
        if (cached != null) {
            return cached;
        }

        int[] needed = new int[26];
        for (char c : remaining.toCharArray()) {
            needed[c - 'a']++;
        }

        int best = Integer.MAX_VALUE;
        int first = remaining.charAt(0) - 'a';

        for (int[] sticker : stickers) {
            // Some sticker must cover this letter; use that sticker first.
            if (sticker[first] == 0) {
                continue;
            }

            StringBuilder next = new StringBuilder();
            for (int letter = 0; letter < 26; letter++) {
                int missing = needed[letter] - sticker[letter];
                for (int j = 0; j < missing; j++) {
                    next.append((char) ('a' + letter));
                }
            }

            int result = solve(next.toString(), stickers, memo);
            if (result != -1) {
                best = Math.min(best, result + 1);
            }
        }

        int answer = best == Integer.MAX_VALUE ? -1 : best;
        memo.put(remaining, answer);
        return answer;
    }
}
