    public int[] restoreArray(int[][] adjacentPairs) {
        Map<Integer, List<Integer>> graph = new HashMap<>();

        for (int[] pair : adjacentPairs) {
            graph.computeIfAbsent(pair[0], key -> new ArrayList<>(2))
                 .add(pair[1]);
            graph.computeIfAbsent(pair[1], key -> new ArrayList<>(2))
                 .add(pair[0]);
        }

        int[] result = new int[adjacentPairs.length + 1];

        for (Map.Entry<Integer, List<Integer>> entry : graph.entrySet()) {
            if (entry.getValue().size() == 1) {
                result[0] = entry.getKey();
                break;
            }
        }

        result[1] = graph.get(result[0]).get(0);

        for (int i = 2; i < result.length; i++) {
            List<Integer> neighbors = graph.get(result[i - 1]);
            result[i] = neighbors.get(0) == result[i - 2]
                    ? neighbors.get(1)
                    : neighbors.get(0);
        }

        return result;
    }
