class Solution {
    private int[][][][] memo;

    public int[] earliestAndLatest(int n, int firstPlayer, int secondPlayer) {
        memo = new int[n + 1][n + 1][n + 1][];
        return solve(n, firstPlayer, secondPlayer);
    }

    private int[] solve(int n, int first, int second) {
        if (first + second == n + 1) {
            return new int[]{1, 1};
        }

        // Reflect the row to merge symmetric states.
        if (first + second > n + 1) {
            int reflectedFirst = n + 1 - second;
            second = n + 1 - first;
            first = reflectedFirst;
        }

        if (memo[n][first][second] != null) {
            return memo[n][first][second];
        }

        int nextN = (n + 1) / 2;

