class Solution {
    public boolean isMatch(String s, String p) {
        int n = s.length();
        int m = p.length();
        boolean[] dp = new boolean[m + 1];
        dp[0] = true;

        for (int j = 1; j <= m; j++) {
            dp[j] = dp[j - 1] && p.charAt(j - 1) == '*';
        }

        for (int i = 1; i <= n; i++) {
            boolean diagonal = dp[0];
            dp[0] = false;
            char current = s.charAt(i - 1);

            for (int j = 1; j <= m; j++) {
                boolean above = dp[j];
                char pattern = p.charAt(j - 1);

                if (pattern == '*') {
                    dp[j] = above || dp[j - 1];
                } else {
                    dp[j] = diagonal && (pattern == '?' || pattern == current);
                }

                diagonal = above;
            }
        }

        return dp[m];
    }
}
