                boolean above = dp[j];
                char pattern = p.charAt(j - 1);

                if (pattern == '*') {
                    dp[j] = above || dp[j - 1];
                } else {
                    dp[j] = diagonal && (pattern == '?' || pattern == current);
                }

                diagonal = above;
            }
        }

        return dp[m];
    }
}
