class Solution {
    public boolean validateBinaryTreeNodes(int n, int[] leftChild, int[] rightChild) {
        int[] indegree = new int[n];

        for (int i = 0; i < n; i++) {
            if (leftChild[i] != -1 && ++indegree[leftChild[i]] > 1) {
                return false;
            }
            if (rightChild[i] != -1 && ++indegree[rightChild[i]] > 1) {
                return false;
            }
        }

        int root = -1;
        for (int i = 0; i < n; i++) {
            if (indegree[i] == 0) {
                if (root != -1) {
                    return false;
                }
                root = i;
            }
        }

        if (root == -1) {
            return false;
        }

        int[] queue = new int[n];
        int head = 0;
        int tail = 0;
        queue[tail++] = root;

        // With at most one parent per node, no cycle is reachable from the root.
        while (head < tail) {
            int node = queue[head++];
            if (leftChild[node] != -1) {
                queue[tail++] = leftChild[node];
            }
            if (rightChild[node] != -1) {
                queue[tail++] = rightChild[node];
            }
        }

        return tail == n;
    }
}
